import { Box, Chip, Paper, Typography } from '@mui/material';
import React from 'react';
import CancelIcon from '@mui/icons-material/Cancel';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import dayjs from 'dayjs';
import { IBillHistory } from '../../core/Interface/billPayment.interface';
import { getPriceFormat } from '../../core/utils';
import { useTranslation } from 'react-i18next';

interface IReloadHistoryProps {
  data?: IBillHistory;
  currencyCode: string;
}

const FieldRow = ({
  label,
  value,
  valueColor,
}: {
  label: string;
  value: string | number;
  valueColor?: string;
}) => (
  <Box sx={{ alignItems: 'center', display: 'flex', justifyContent: 'space-between', py: 0.4 }}>
    <Typography
      sx={{
        color: '#94A3B8',
        fontSize: '0.75rem',
        fontWeight: 600,
        letterSpacing: '0.03em',
        textTransform: 'uppercase',
      }}
    >
      {label}
    </Typography>
    <Typography sx={{ color: valueColor ?? '#1E293B', fontSize: '0.84rem', fontWeight: 600 }}>
      {value}
    </Typography>
  </Box>
);

const ReloadHistoryGridItem = ({ data, currencyCode }: IReloadHistoryProps) => {
  const { t } = useTranslation(['billPayment']);
  const isFailed = data?.status === 3;

  return (
    <Paper
      sx={{
        border: `1px solid ${isFailed ? '#FEE2E2' : '#E2E8F0'}`,
        borderRadius: '12px',
        boxShadow: 'none',
        overflow: 'hidden',
        transition: 'box-shadow 0.15s',
        '&:hover': { boxShadow: '0 4px 16px rgba(0,0,0,0.08)' },
      }}
    >
      {/* Card header */}
      <Box
        sx={{
          alignItems: 'center',
          background: isFailed ? '#FEF2F2' : '#F8FAFC',
          borderBottom: `1px solid ${isFailed ? '#FEE2E2' : '#E2E8F0'}`,
          display: 'flex',
          justifyContent: 'space-between',
          px: 2,
          py: 1.5,
        }}
      >
        <Box sx={{ minWidth: 0 }}>
          <Typography
            noWrap
            sx={{ color: '#0F1D4D', fontSize: '0.92rem', fontWeight: 700 }}
          >
            {data?.accountNo || '—'}
          </Typography>
          {data?.providerName && (
            <Typography sx={{ color: '#64748B', fontSize: '0.78rem', fontWeight: 500 }}>
              {data.providerName}
            </Typography>
          )}
        </Box>
        <Box sx={{ alignItems: 'flex-end', display: 'flex', flexDirection: 'column', flexShrink: 0, gap: 0.5, ml: 1 }}>
          <Typography
            sx={{ color: isFailed ? '#DC2626' : '#0F8B8D', fontSize: '1rem', fontWeight: 800 }}
          >
            {getPriceFormat(data?.amount || 0, currencyCode)}
          </Typography>
          <Chip
            icon={
              isFailed ? (
                <CancelIcon sx={{ fontSize: '13px !important' }} />
              ) : (
                <CheckCircleIcon sx={{ fontSize: '13px !important' }} />
              )
            }
            label={isFailed ? data?.updatedStatus || 'Failed' : 'Success'}
            size="small"
            sx={{
              background: isFailed ? '#FEE2E2' : '#DCFCE7',
              border: 'none',
              borderRadius: '4px',
              color: isFailed ? '#DC2626' : '#16A34A',
              fontSize: '0.7rem',
              fontWeight: 700,
              height: 20,
            }}
          />
        </Box>
      </Box>

      {/* Card body */}
      <Box sx={{ px: 2, py: 1.5 }}>
        <FieldRow label={t('billPayment:cost')} value={data?.actualCost ?? '—'} />
        <FieldRow
          label={t('billPayment:earning')}
          value={data?.merchantEarning ?? '—'}
          valueColor="#16A34A"
        />
        <FieldRow label={t('billPayment:previousBalance')} value={data?.preBal ?? '—'} />
        <FieldRow
          label={t('billPayment:afterBalance')}
          value={data?.aftrBal ?? '—'}
          valueColor="#0F8B8D"
        />
        <Box sx={{ borderTop: '1px solid #E2E8F0', mt: 1, pt: 1 }}>
          <Typography sx={{ color: '#94A3B8', fontSize: '0.75rem', fontWeight: 500 }}>
            {t('billPayment:datetime')}:{' '}
            {dayjs(data?.createdOn).format('DD MMM YYYY, HH:mm')}
          </Typography>
        </Box>
      </Box>
    </Paper>
  );
};

export default React.memo(ReloadHistoryGridItem);
