import React, { useMemo, useState } from 'react';
import {
  Box,
  Button,
  CircularProgress,
  Grid,
  InputAdornment,
  Paper,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import HistoryIcon from '@mui/icons-material/History';
import SearchIcon from '@mui/icons-material/Search';
import { useTranslation } from 'react-i18next';
import { useGetAllBillHistoryQuery, useGetUserQuery } from '../posApi';
import { IUserInfo } from '../../core/Interface/user.interface';
import ReloadHistoryGridItem from './ReloadHistoryGridItem';
import { IBillHistory } from '../../core/Interface/billPayment.interface';
import { HEADER_GRADIENT } from '../../theme/appColors';

const BillHistory = () => {
  const { data, isLoading } = useGetAllBillHistoryQuery({});
  const [search, setSearch] = useState('');
  const [searchInput, setSearchInput] = useState('');
  const { t } = useTranslation(['billPayment']);

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) return userData.company.currencyCode;
    }
    return '';
  }, [companyData]);

  const historyList = useMemo(() => {
    if (data?.status && data.data) {
      const history = data.data as IBillHistory[];
      return history.filter((d) => d.accountNo.includes(search));
    }
    return [];
  }, [data?.data, data?.status, search]);

  return (
    <Box>
      {/* Page header */}
      <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2.5 }}>
        <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
          <Box
            sx={{
              alignItems: 'center',
              background: 'rgba(255,255,255,0.15)',
              borderRadius: '10px',
              display: 'flex',
              height: 40,
              justifyContent: 'center',
              width: 40,
            }}
          >
            <HistoryIcon sx={{ color: '#fff', fontSize: 22 }} />
          </Box>
          <Box>
            <Typography sx={{ color: '#fff', fontSize: 17, fontWeight: 800, lineHeight: 1.2 }}>
              Bill History
            </Typography>
            <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 11, fontWeight: 500 }}>
              View all payment transactions
            </Typography>
          </Box>
        </Box>
      </Box>

      <Box sx={{ p: 2 }}>
        {isLoading ? (
          <Stack alignItems="center" sx={{ mt: 8 }}>
            <CircularProgress />
          </Stack>
        ) : !data?.status ? (
          <Typography align="center" sx={{ fontWeight: 600, fontSize: '1.1rem', p: 3 }}>
            {data?.message || 'An error occurred. Please contact admin.'}
          </Typography>
        ) : (
          <>
            {/* Search bar */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5, mb: 3 }}>
              <TextField
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: '#94A3B8', fontSize: 18 }} />
                    </InputAdornment>
                  ),
                }}
                autoComplete="off"
                onChange={(e) => setSearchInput(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') setSearch(searchInput); }}
                placeholder={t('billPayment:acountNumber')}
                size="small"
                sx={{
                  maxWidth: 400,
                  width: '100%',
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '8px',
                    '& fieldset': { borderColor: '#CBD5E1' },
                    '&:hover fieldset': { borderColor: '#0F8B8D' },
                    '&.Mui-focused fieldset': { borderColor: '#0F8B8D' },
                  },
                }}
                value={searchInput}
              />
              <Button
                onClick={() => setSearch(searchInput)}
                sx={{ borderRadius: '8px', flexShrink: 0, fontWeight: 600, height: 40, px: 2.5 }}
                variant="contained"
              >
                Search
              </Button>
            </Box>

            {historyList.length === 0 ? (
              <Paper
                sx={{
                  alignItems: 'center',
                  border: '1px solid #E2E8F0',
                  borderRadius: '12px',
                  boxShadow: 'none',
                  display: 'flex',
                  justifyContent: 'center',
                  py: 6,
                }}
              >
                <Typography sx={{ color: '#94A3B8', fontSize: '0.9rem' }}>
                  No payment history found
                </Typography>
              </Paper>
            ) : (
              <Grid container spacing={2}>
                {historyList.map((his, i) => (
                  <Grid item key={i} lg={4} md={4} sm={6} xs={12}>
                    <ReloadHistoryGridItem currencyCode={currencyCode} data={his} />
                  </Grid>
                ))}
              </Grid>
            )}
          </>
        )}
      </Box>
    </Box>
  );
};

export default BillHistory;
